import{useEffect,useState}from"react";import{getMyVendor,createVendor,updateMyVendor}from"../../api/vendorApi";

const empty={businessName:"",businessType:"",description:"",phone:"",email:"",logo:"",address:"",documents:[]};
export default function VendorProfile(){const[f,setF]=useState(empty),[exists,setExists]=useState(false),[loading,setLoading]=useState(true),[msg,setMsg]=useState(""),[error,setError]=useState("");
useEffect(()=>{getMyVendor().then(r=>{setF({...empty,...(r.data?.data||{})});setExists(true)}).catch(e=>{if(e.response?.status===404){setExists(false);setMsg("Create your vendor profile. It will be sent to admin for approval.")}else setError(e.response?.data?.message||"Could not load vendor profile")}).finally(()=>setLoading(false))},[]);
const change=(k,v)=>setF(x=>({...x,[k]:v}));
const save=async e=>{e.preventDefault();setError("");setMsg("");try{const r=exists?await updateMyVendor(f):await createVendor(f);setF({...empty,...(r.data?.data||f)});setExists(true);setMsg(exists?"Vendor profile updated successfully":"Vendor profile submitted. Wait for admin approval before creating listings.")}catch(e){setError(e.response?.data?.message||"Could not save vendor profile")}};
if(loading)return <div className="mx-auto max-w-4xl px-4 py-8"><p className="text-slate-500">Loading vendor profile…</p></div>;
return <div className="mx-auto max-w-4xl px-4 py-8"><p className="text-sm text-slate-400">VENDOR</p><h1 className="text-3xl font-black">{exists?"Vendor profile":"Create vendor profile"}</h1><p className="mt-1 text-sm text-slate-500">{exists?"Keep your business information up to date.":"Complete your business information before creating listings."}</p>{msg&&<div className="my-4 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-700">{msg}</div>}{error&&<div className="my-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</div>}<form onSubmit={save} className="card mt-6 space-y-5 p-6"><div className="grid gap-4 sm:grid-cols-2"><div><label className="label">Business name *</label><input className="input" value={f.businessName||""} onChange={e=>change("businessName",e.target.value)} required/></div><div><label className="label">Business type</label><input className="input" value={f.businessType||""} onChange={e=>change("businessType",e.target.value)} placeholder="Retail, Services, Tutor, Agency…"/></div></div><div><label className="label">Business description</label><textarea className="input" rows="4" value={f.description||""} onChange={e=>change("description",e.target.value)} placeholder="Describe your business"/></div><div className="grid gap-4 sm:grid-cols-2"><div><label className="label">Business phone</label><input className="input" value={f.phone||""} onChange={e=>change("phone",e.target.value)}/></div><div><label className="label">Business email</label><input type="email" className="input" value={f.email||""} onChange={e=>change("email",e.target.value)}/></div></div><div><label className="label">Logo URL</label><input className="input" value={f.logo||""} onChange={e=>change("logo",e.target.value)} placeholder="Cloudinary logo URL (optional)"/></div><div><label className="label">Business address</label><textarea className="input" rows="3" value={typeof f.address==="string"?f.address:""} onChange={e=>change("address",e.target.value)} placeholder="Full business address"/></div>{exists&&<div className="rounded-xl bg-slate-50 p-4 text-sm">Verification status: <b>{f.verificationStatus||"PENDING"}</b>{f.verificationStatus!=="APPROVED"&&<p className="mt-1 text-slate-500">Admin approval is required before you can publish listings.</p>}</div>}<div className="flex justify-end"><button className="btn-primary">{exists?"Save profile":"Submit vendor profile"}</button></div></form></div>}
